BEGIN;

CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL, "codename" varchar(100) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "api_userprofile" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL UNIQUE, "avatar" varchar(100) NULL, "email_verified" boolean NOT NULL, "email_verification_token" varchar(100) NULL, "balance" numeric(10, 2) NOT NULL, "subscription_type" varchar(20) NOT NULL, "subscription_expires_at" timestamp with time zone NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "api_server" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(120) NOT NULL, "host" varchar(255) NOT NULL, "port" integer NOT NULL CHECK ("port" >= 0), "username" varchar(120) NOT NULL, "auth_type" varchar(20) NOT NULL, "password" varchar(255) NOT NULL, "private_key" text NOT NULL, "passphrase" varchar(255) NOT NULL, "created_by_id" integer NULL, "is_active" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "api_transaction" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "transaction_type" varchar(20) NOT NULL, "amount" numeric(10, 2) NOT NULL, "description" text NOT NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "api_allocatedserver" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "name" varchar(120) NOT NULL, "host" varchar(255) NOT NULL, "port" integer NOT NULL CHECK ("port" >= 0), "username" varchar(120) NOT NULL, "password" varchar(255) NOT NULL, "cpu_cores" integer NOT NULL CHECK ("cpu_cores" >= 0), "memory_gb" integer NOT NULL CHECK ("memory_gb" >= 0), "disk_gb" integer NOT NULL CHECK ("disk_gb" >= 0), "is_active" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "expires_at" timestamp with time zone NULL);
CREATE TABLE "api_servermetric" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "server_id" bigint NULL, "allocated_server_id" bigint NULL, "cpu_percent" double precision NULL, "memory_percent" double precision NULL, "memory_used_mb" double precision NULL, "memory_total_mb" double precision NULL, "disk_percent" double precision NULL, "disk_used_gb" double precision NULL, "disk_total_gb" double precision NULL, "network_in_mb" double precision NULL, "network_out_mb" double precision NULL, "created_at" timestamp with time zone NOT NULL);
